61	  x: z.literal(0),
62	  y: z.literal(0),
63	  encoding: z.literal("csv").optional(),
64	  compression: z.undefined().optional(),
65	  data: z.array(z.int().positive()),
66	});
67	
68	const objectSchema = z.object({
69	  id: z.int(),
70	  name: z.string(),
71	  type: z.enum(["island", "spawn", "hub", "final-socket"]),
72	  x: z.number(),
73	  y: z.number(),
74	  width: z.number().nonnegative(),
75	  height: z.number().nonnegative(),
76	  rotation: z.literal(0).optional(),
77	  point: z.boolean().optional(),
78	  properties: z.array(propertySchema).optional(),
79	});
80	
81	const objectLayerSchema = z.object({
82	  type: z.literal("objectgroup"),
83	  name: z.literal("objects"),
84	  objects: z.array(objectSchema),
85	});
86	
87	export const tiledMapSchema = z.object({
88	  type: z.literal("map"),
89	  orientation: z.literal("orthogonal"),
90	  infinite: z.literal(false),
91	  width: z.int().positive(),
92	  height: z.int().positive(),
93	  tilewidth: z.literal(TILE_PIXELS),
94	  tileheight: z.literal(TILE_PIXELS),
95	  tilesets: z.tuple([tilesetSchema]),
96	  layers: z.tuple([tileLayerSchema, objectLayerSchema]),
97	});
98	
99	export type TiledMap = z.infer<typeof tiledMapSchema>;
100	type TiledObject = z.infer<typeof objectSchema>;
101	
102	const CHAR_BY_TERRAIN: Readonly<Record<Terrain, string>> = Object.fromEntries(
103	  Object.entries(TERRAIN_CHARS).map(([char, kind]) => [kind, char]),
104	) as Record<Terrain, string>;
105	
106	const OBJECT_PROPERTIES: Readonly<Record<TiledObject["type"], readonly string[]>> = {
107	  island: ["theme"],
108	  spawn: ["slot", "facing"],
109	  hub: [],
110	  "final-socket": ["claimX", "claimY"],
111	};
112	
113	function property(object: TiledObject, name: string): string | number | undefined {
114	  return object.properties?.find((entry) => entry.name === name)?.value;
115	}
116	
117	/** Converts a parsed `.tmj` into the map source the content module holds. Refuses anything outside the subset. */
118	export function convertTiledMap(name: string, candidate: unknown): ValidationResult<SeaMapSource> {
119	  const parsed = tiledMapSchema.safeParse(candidate);
120	  if (!parsed.success) return { ok: false, issues: formatIssues(parsed.error) };
121	  const map = parsed.data;
122	  const [tileset] = map.tilesets;
123	  const [terrainLayer, objectLayer] = map.layers;
124	  const issues: string[] = [];
125	
126	  const terrainByGid = new Map<number, Terrain>();
127	  for (const tile of tileset.tiles) {
128	    if (tile.id >= tileset.tilecount) issues.push(`tileset: tile ${tile.id} is beyond its ${tileset.tilecount} tiles`);
129	    terrainByGid.set(tileset.firstgid + tile.id, TERRAIN_TYPES[tile.type]);
130	  }
131	  if (terrainLayer.width !== map.width || terrainLayer.height !== map.height) {
132	    issues.push(`terrain: layer is ${terrainLayer.width} × ${terrainLayer.height}, map is ${map.width} × ${map.height}`);
133	  }
134	  if (terrainLayer.data.length !== map.width * map.height) {
135	    issues.push(`terrain: ${terrainLayer.data.length} tiles for a ${map.width} × ${map.height} map`);
136	  }
137	  const rows: string[] = [];
138	  for (let tileY = 0; tileY < map.height && issues.length === 0; tileY++) {
139	    let row = "";
140	    for (let tileX = 0; tileX < map.width; tileX++) {
141	      const gid = terrainLayer.data[tileY * map.width + tileX]!;
142	      const kind = terrainByGid.get(gid);
143	      if (kind === undefined) {
144	        issues.push(`terrain: tile ${tileX},${tileY} has gid ${gid}, which has no terrain type`);
145	        break;
146	      }
147	      row += CHAR_BY_TERRAIN[kind];
148	    }
149	    rows.push(row);
150	  }
151	
152	  const islands: IslandSource[] = [];
153	  const spawns: { slot: number; spawn: SpawnSlot }[] = [];
154	  const hubs: TilePoint[] = [];
155	  const finalSockets: FinalSocket[] = [];
156	  for (const object of objectLayer.objects) {
157	    const where = `object ${object.id} (${object.type} "${object.name}")`;
158	    const allowed = OBJECT_PROPERTIES[object.type];
159	    for (const entry of object.properties ?? []) {
160	      if (!allowed.includes(entry.name)) issues.push(`${where}: unknown property "${entry.name}"`);
161	    }
